  /** @default 4000 */
  stack?: number;
  /** @default 100 */
  scope?: number;
  /** @default 500 */
  url?: number;
  /** @default 300 */
  userAgent?: number;
  /** Cap on the JSON-serialized `context`; over it, a marker replaces it. @default 2000 */
